package agentusageview

import (
	"strings"
	"testing"
	"time"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-151 step 4: the footer writes the selected agent's state in words
// (the dot repeats it), and the help carries the legend.

// agentDetailer is looked up through an interface so the tests fail on their
// own message before agentDetail exists, not on a compile error.
type agentDetailer interface {
	agentDetail() components.RowDetail
}

func detailOf(t *testing.T, m Model) components.RowDetail {
	t.Helper()
	v, ok := any(m).(agentDetailer)
	if !ok {
		t.Fatal("agentusageview.Model has no agentDetail() components.RowDetail")
	}
	return v.agentDetail()
}

// session at the agents level; alive=false is a paused session.
func sessionOf(t *testing.T, alive bool, agents ...agentusage.Agent) Model {
	t.Helper()
	m := withSessions(t, "/p/a.jsonl")
	m, _ = opened(t, m, "right")
	m.clock = statusClock{now: time.Now(), alive: alive}
	return answer(t, m, agentusage.Usage{Agents: agents})
}

func selectRow(t *testing.T, m Model, downs int) Model {
	t.Helper()
	for range downs {
		m, _ = opened(t, m, "down")
	}
	return m
}

func footerLine(m Model) string {
	lines := strings.Split(ansi.Strip(m.RenderFooter(160)), "\n")
	return strings.TrimSpace(lines[len(lines)-1])
}

func TestTheFooterWritesTheStateOfTheSelectedAgent(t *testing.T) {
	// recent() puts FirstActivity one minute before LastActivity: ran 1m00s.
	liveOrch := recent(orchestrator(10, 0), agentusage.StateUnknown, 2*time.Minute)
	tests := []struct {
		name  string
		alive bool
		agent agentusage.Agent
		down  int
		state indicator.State
		want  string
	}{
		{"running", true, recent(subAgent("a01", "coder", 5, 0), agentusage.StateUnfinished, 2*time.Minute), 1,
			indicator.Running, "Agent running — last transcript line 2 min ago"},
		{"idle", true, recent(subAgent("a01", "coder", 5, 0), agentusage.StateUnfinished, 10*time.Minute), 1,
			indicator.Suspended, "Agent idle — last transcript line 10 min ago"},
		{"done", true, recent(subAgent("a01", "coder", 5, 0), agentusage.StateFinished, time.Hour), 1,
			indicator.Done, "Agent done — ran 1m00s"},
		{"unknown sub-agent", false, recent(subAgent("a01", "coder", 5, 0), agentusage.StateUnknown, time.Hour), 1,
			indicator.Unknown, "Agent state unknown — transcript has no end marker"},
		{"unknown orchestrator", false, recent(orchestrator(10, 0), agentusage.StateUnknown, time.Hour), 0,
			indicator.Unknown, "Agent state unknown — updates are paused"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var m Model
			if tt.down == 0 {
				m = sessionOf(t, tt.alive, tt.agent)
			} else {
				m = selectRow(t, sessionOf(t, tt.alive, liveOrch, tt.agent), tt.down)
			}
			want := components.DescribeRow(components.RowQuery{Observed: tt.state, ObservedText: tt.want}).Detail
			if got := detailOf(t, m); got != want {
				t.Fatalf("agentDetail = %+v, want %+v", got, want)
			}
			if got := m.status().Detail; got != want {
				t.Errorf("status Detail = %+v, want the agentDetail %+v", got, want)
			}
			if line, wantLine := footerLine(m), indicator.Glyph(tt.state, true)+" "+tt.want; !strings.Contains(line, wantLine) {
				t.Errorf("footer line = %q, want it to contain %q", line, wantLine)
			}
		})
	}
}

func TestTheFooterFollowsTheCursor(t *testing.T) {
	m := runningTeam(t) // idle orchestrator, running coder, done tester
	for down, want := range []string{"Agent idle", "Agent running", "Agent done"} {
		if line := footerLine(selectRow(t, m, down)); !strings.Contains(line, want) {
			t.Errorf("cursor %d: footer line = %q, want %q", down, line, want)
		}
	}
}

func TestNoAgentDetailOutsideTheAgentsTab(t *testing.T) {
	m := runningTeam(t)
	m.tab = tabBreakdown
	if d := detailOf(t, m); !d.IsZero() {
		t.Errorf("Breakdown tab carries a detail: %+v", d)
	}
	if line := footerLine(m); strings.Contains(line, "Agent ") {
		t.Errorf("Breakdown footer = %q", line)
	}
	top := withSessions(t, "/p/a.jsonl")
	if !top.status().Detail.IsZero() {
		t.Errorf("sessions level carries a detail: %+v", top.status().Detail)
	}
}

func TestAReadErrorStillWinsOverTheAgentDetail(t *testing.T) {
	m := runningTeam(t)
	m.agentsErr = true
	st := m.status()
	if st.Level != components.LevelError || !strings.Contains(st.Text, "Failed to read this session") {
		t.Errorf("status = %+v, want the read error kept", st)
	}
	if !st.Detail.IsZero() {
		t.Errorf("an error status carries the row detail %+v", st.Detail)
	}
	m = runningTeam(t)
	m.agentsLoading = true
	if st := m.status(); !st.Spinner || !st.Detail.IsZero() {
		t.Errorf("a loading status = %+v, want the spinner alone", st)
	}
}

func TestTheHelpCarriesTheActivityLegend(t *testing.T) {
	want := indicator.Legend(indicator.AgentsLegend...)
	var found bool
	for _, s := range runningTeam(t).GetHelpContent().Sections {
		if s.Title == want.Title {
			found = true
			if s.Body != want.Body {
				t.Errorf("legend body = %q, want %q", s.Body, want.Body)
			}
		}
	}
	if !found {
		t.Fatalf("no %q section in the help", want.Title)
	}
	for _, line := range []string{"idle (no activity for 5 min)", "done", "unknown"} {
		if !strings.Contains(want.Body, line) {
			t.Fatalf("the agents legend lost %q", line)
		}
	}
}

func TestTheActivityFooterAddsNoShortcut(t *testing.T) {
	want := strings.Join(testutil.ShortcutKeys(withSessionsAtAgents(t).GetShortcuts()), ",")
	got := strings.Join(testutil.ShortcutKeys(runningTeam(t).GetShortcuts()), ",")
	if got != want {
		t.Errorf("shortcuts changed with live agents: %q, want %q", got, want)
	}
}

func withSessionsAtAgents(t *testing.T) Model {
	t.Helper()
	m := withSessions(t, "/p/a.jsonl")
	m, _ = opened(t, m, "right")
	return answer(t, m, agentusage.Usage{Agents: []agentusage.Agent{orchestrator(10, 0)}})
}
package agentusageview

import (
	"strings"
	"testing"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/agentusage/pricing"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// DEVDESK-151 step 5: Est. cost is coloured by the agent's share of the
// session's estimated cost. This is the D6 exception (a share of money, not an
// activity colour). Below LoadWarnPercent the cell is neutral: LoadTextStyle
// would paint it green there, and a green cost says "good", which it does not.

func TestEstCostColourFollowsTheCostShare(t *testing.T) {
	col := column(t, costTitle)
	none := lipgloss.NewStyle().GetForeground()
	dim := theme.DimStyle.GetForeground()
	medium := lipgloss.TerminalColor(theme.ColorSeverityMedium)
	critical := lipgloss.TerminalColor(theme.ColorSeverityCritical)
	tests := []struct {
		name string
		row  agentRow
		want lipgloss.TerminalColor
	}{
		{"74.9 is neutral", agentRow{Agent: orchestrator(1, 0), cost: priced(1), costPct: 74.9, costRanked: true}, none},
		{"75 is orange", agentRow{Agent: orchestrator(1, 0), cost: priced(1), costPct: 75, costRanked: true}, medium},
		{"89.9 is orange", agentRow{Agent: orchestrator(1, 0), cost: priced(1), costPct: 89.9, costRanked: true}, medium},
		{"90 is red", agentRow{Agent: orchestrator(1, 0), cost: priced(1), costPct: 90, costRanked: true}, critical},
		{"100 is red", agentRow{Agent: orchestrator(1, 0), cost: priced(1), costPct: 100, costRanked: true}, critical},
		{"0 is neutral, never green", agentRow{Agent: orchestrator(1, 0), cost: priced(1), costPct: 0, costRanked: true}, none},
		{"60 is neutral, never green", agentRow{Agent: orchestrator(1, 0), cost: priced(1), costPct: 60, costRanked: true}, none},
		{"a share nobody ranked is neutral even at 95", agentRow{Agent: orchestrator(1, 0), cost: priced(1), costPct: 95, costRanked: false}, none},
		{"a sub-agent follows the same thresholds", agentRow{Agent: subAgent("a", "coder", 1, 0), cost: priced(1), costPct: 92, costRanked: true}, critical},
		{"unpriced is dim whatever the share", agentRow{Agent: orchestrator(1, 0), cost: pricing.Estimate{Status: pricing.Unpriced}, costPct: 95, costRanked: true}, dim},
		{"no tokens is dim", agentRow{Agent: subAgent("a", "coder", 0, 0), cost: pricing.Estimate{Status: pricing.NoTokens}}, dim},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := col.Style(tt.row).GetForeground(); got != tt.want {
				t.Errorf("foreground = %v, want %v", got, tt.want)
			}
		})
	}
}

func TestEstCostColourDoesNotChangeTheCellText(t *testing.T) {
	col := column(t, costTitle)
	r := agentRow{Agent: orchestrator(1, 0), cost: priced(1.5), costPct: 95, costRanked: true}
	plain := r
	plain.costPct, plain.costRanked = 0, false
	if col.Cell(r) != col.Cell(plain) || col.Cell(r) != "~$1.50" {
		t.Errorf("cell = %q / %q, want the same plain ~$1.50 whatever the share", col.Cell(r), col.Cell(plain))
	}
}

// End to end: the shares come out of agentRows, from the session's estimates.
// model-a costs 10 per million output tokens (pricesYAML).
func TestEstCostColourComesFromTheSessionShares(t *testing.T) {
	prices, _ := pricing.FromConfig(cfgWith(t, pricesYAML).AgentUsage.Prices)
	col := column(t, costTitle)
	none := lipgloss.NewStyle().GetForeground()
	dim := theme.DimStyle.GetForeground()
	out := func(a agentusage.Agent, k int64) agentusage.Agent {
		return byModel(a, mu("model-a", agentusage.Tokens{Output: k}, 0))
	}
	fg := func(r agentRow) lipgloss.TerminalColor { return col.Style(r).GetForeground() }

	t.Run("95 and 5", func(t *testing.T) {
		u := agentusage.Usage{Agents: []agentusage.Agent{
			out(agentusage.Agent{Main: true}, 950_000), out(agentusage.Agent{ID: "a01", Type: "coder"}, 50_000)}}
		rows := agentRows(u, true, statusClock{}, prices)
		if got := fg(rows[0]); got != lipgloss.TerminalColor(theme.ColorSeverityCritical) {
			t.Errorf("orchestrator at 95%% = %v, want critical", got)
		}
		if got := fg(rows[1]); got != none {
			t.Errorf("sub-agent at 5%% = %v, want neutral", got)
		}
	})
	t.Run("80 and 20", func(t *testing.T) {
		u := agentusage.Usage{Agents: []agentusage.Agent{
			out(agentusage.Agent{Main: true}, 800_000), out(agentusage.Agent{ID: "a01", Type: "coder"}, 200_000)}}
		rows := agentRows(u, true, statusClock{}, prices)
		if got := fg(rows[0]); got != lipgloss.TerminalColor(theme.ColorSeverityMedium) {
			t.Errorf("orchestrator at 80%% = %v, want orange", got)
		}
	})
	t.Run("60 and 40", func(t *testing.T) {
		u := agentusage.Usage{Agents: []agentusage.Agent{
			out(agentusage.Agent{Main: true}, 600_000), out(agentusage.Agent{ID: "a01", Type: "coder"}, 400_000)}}
		for i, r := range agentRows(u, true, statusClock{}, prices) {
			if got := fg(r); got != none {
				t.Errorf("row %d at 60/40 = %v, want neutral", i, got)
			}
		}
	})
	t.Run("a single priced agent colours nothing", func(t *testing.T) {
		u := agentusage.Usage{Agents: []agentusage.Agent{
			out(agentusage.Agent{Main: true}, 1_000_000), {ID: "a01", Type: "coder"}}}
		rows := agentRows(u, true, statusClock{}, prices)
		if got := fg(rows[0]); got != none {
			t.Errorf("lone priced agent at 100%% = %v, want neutral", got)
		}
		if got := fg(rows[1]); got != dim {
			t.Errorf("unpriced agent = %v, want dim", got)
		}
	})
	t.Run("no price table: every cell is a dim dash", func(t *testing.T) {
		u := agentusage.Usage{Agents: []agentusage.Agent{
			out(agentusage.Agent{Main: true}, 950_000), out(agentusage.Agent{ID: "a01", Type: "coder"}, 50_000)}}
		for i, r := range agentRows(u, true, statusClock{}, pricing.Table{}) {
			if got := fg(r); got != dim {
				t.Errorf("row %d = %v, want dim", i, got)
			}
		}
	})
}

func TestTheHelpSaysWhatTheCostColoursMean(t *testing.T) {
	var body string
	for _, s := range runningTeam(t).GetHelpContent().Sections {
		if s.Title == "Costs" {
			body = s.Body
		}
	}
	if body == "" {
		t.Fatal("no Costs section in the help")
	}
	for _, want := range []string{"75%", "90%"} {
		if !strings.Contains(body, want) {
			t.Errorf("Costs help does not mention %s as a colour threshold:\n%s", want, body)
		}
	}
}
package agentusageview

import (
	"time"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// runState is what the State column shows for an agent.
type runState int

const (
	stateUnknown runState = iota
	stateRunning
	stateIdle
	stateDone
)

// label returns the text shown in the State column.
func (s runState) label() string {
	switch s {
	case stateRunning:
		return "running"
	case stateIdle:
		return "idle"
	case stateDone:
		return "done"
	default:
		return "unknown"
	}
}

// indicator maps the state onto the activity column's state, so the dot
// repeats what the State column says.
func (s runState) indicator() indicator.State {
	switch s {
	case stateRunning:
		return indicator.Running
	case stateIdle:
		return indicator.Suspended
	case stateDone:
		return indicator.Done
	default:
		return indicator.Unknown
	}
}

// statusClock is what the states are computed against: when the last read
// finished, and whether the session counts as alive (not Settled).
type statusClock struct {
	now   time.Time
	alive bool
}

// quiet reports whether the agent has been silent for strictly more than
// idleAfter. An agent with no timestamp, or one stamped in the future, is
// never quiet.
func (c statusClock) quiet(a agentusage.Agent) bool {
	if a.LastActivity.IsZero() {
		return false
	}
	return c.now.Sub(a.LastActivity) > idleAfter
}

// running is the state of an agent that has not finished: running, or idle
// once it has been silent for long enough.
func (c statusClock) running(a agentusage.Agent) runState {
	if c.quiet(a) {
		return stateIdle
	}
	return stateRunning
}

// subAgentState is the state of one sub-agent. A finished one is done; an
// unfinished one is running or idle whether or not the session is alive; one
// whose meta says nothing is judged the same way while the session is alive,
// and is unknown once it is not.
func (c statusClock) subAgentState(a agentusage.Agent) runState {
	switch {
	case a.State == agentusage.StateFinished:
		return stateDone
	case a.State == agentusage.StateUnfinished || c.alive:
		return c.running(a)
	default:
		return stateUnknown
	}
}

// orchestratorState is the state of the orchestrator, which no file says is
// finished: unknown when the session is not alive, idle only if it has been
// silent for long enough and no sub-agent is running, running otherwise.
func (c statusClock) orchestratorState(a agentusage.Agent, subRunning bool) runState {
	if !c.alive {
		return stateUnknown
	}
	if subRunning {
		return stateRunning
	}
	return c.running(a)
}

// agentStates returns one state per agent, same order. It is pure: the
// clock is a parameter.
func agentStates(agents []agentusage.Agent, c statusClock) []runState {
	out := make([]runState, len(agents))
	subRunning := false
	for i, a := range agents {
		if a.Main {
			continue
		}
		out[i] = c.subAgentState(a)
		subRunning = subRunning || out[i] == stateRunning
	}
	for i, a := range agents {
		if a.Main {
			out[i] = c.orchestratorState(a, subRunning)
		}
	}
	return out
}
package agentusageview

import (
	"fmt"
	"log"
	"math"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/agentusage/pricing"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/datatable"
)

const (
	// minus is the real minus sign (U+2212), never an ASCII hyphen.
	minus = "−"
	// estimateMark prefixes an amount computed from a user-written price table.
	estimateMark = "~"
	// costWidth fits the widest sub-agent cell, "≥ ~$999.99".
	costWidth = 10
	// wholeDollarsFrom is where cents stop being shown.
	wholeDollarsFrom = 999.995
	// maxDollars is the largest amount shown exactly; past it the cell saturates.
	maxDollars = 99999.5
	// saturated is what formatUSD shows past maxDollars: "at least".
	saturated = "$99999+"
)

// formatUSD renders an amount: two decimals up to $999.99, whole dollars from
// $1000, "$99999+" past $99999. A non-zero amount under half a cent is
// "<$0.01", never "$0.00"; a negative one keeps its sign ("−<$0.01"). NaN and
// the infinities are unknown amounts and show a dash. The estimate mark is costCell's, not this function's.
func formatUSD(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return noValue
	}
	if v < 0 {
		return minus + formatUSD(-v)
	}
	switch {
	case v >= maxDollars:
		return saturated
	case v >= wholeDollarsFrom:
		return fmt.Sprintf("$%.0f", math.Floor(v+0.5))
	case v > 0 && v < 0.005:
		return "<$0.01"
	}
	return fmt.Sprintf("$%.2f", v)
}

// costCell is the Est. cost cell: an estimate for the orchestrator, a floor
// (partialMark) for a sub-agent, whose transcript may be incomplete; a dash
// when the cost is unknown. A saturated amount already means "at least", so a
// sub-agent drops the floor mark to stay within costWidth.
func costCell(r agentRow) string {
	if r.cost.Status != pricing.Priced {
		return noValue
	}
	amount := formatUSD(r.cost.USD)
	if r.Main || amount == saturated {
		return estimateMark + amount
	}
	return partialMark + estimateMark + amount
}

// costColumn is the Est. cost column. It has no Less: `.` keeps cycling Total.
func costColumn() datatable.Column[agentRow] {
	return datatable.Column[agentRow]{
		Title: "Est. cost", Sizing: datatable.SizingFixed, MinWidth: costWidth, Optional: true, DropFirst: true, YieldsToContent: true,
		Cell:  costCell,
		Style: func(r agentRow) lipgloss.Style { return dimWhen(r.cost.Status != pricing.Priced) },
	}
}

// pricesFrom builds the price table of a context. The table is read once, when
// the view is built, and a rejected entry is logged once, naming the user's key.
func pricesFrom(cfg *config.Config) pricing.Table {
	if cfg == nil {
		return pricing.Table{}
	}
	table, problems := pricing.FromConfig(cfg.AgentUsage.Prices)
	for _, p := range problems {
		log.Printf("WARN [agentusageview] agent_usage.prices %q: %s", p.Key, p.Reason)
	}
	return table
}

// costShares returns each agent's share of the session's estimated cost, in
// percent, in the order of ests. Agents without a priced estimate get 0 and
// stay out of the denominator. ranked is false when fewer than two agents are
// priced or the priced sum is not a positive number: a share of one is noise.
func costShares(ests []pricing.Estimate) (pct []float64, ranked bool) {
	pct = make([]float64, len(ests))
	var sum float64
	priced := 0
	for _, e := range ests {
		if e.Status == pricing.Priced {
			sum += e.USD
			priced++
		}
	}
	if priced < 2 || math.IsNaN(sum) || math.IsInf(sum, 0) || sum <= 0 {
		return pct, false
	}
	for i, e := range ests {
		if e.Status == pricing.Priced {
			pct[i] = e.USD / sum * 100
		}
	}
	return pct, true
}
package agentusageview

import "github.com/anthnel/devdesk/internal/ui/help"

// GetHelpContent returns the help for `?` (Rule 114).
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title: "Agent usage",
		Description: "The Claude Code sessions found on this machine, newest first. " +
			"Only where and when a session ran is read — nothing a session says.",
		KeyBindings: []help.KeyBinding{
			{Key: "ctrl+r", Description: "Re-read the whole session from the start (at the sessions level: read the sessions again)"},
			{Key: "→/enter", Description: "Open the selected session's agents"},
			{Key: "←/esc", Description: "Back to the sessions"},
			{Key: "tab", Description: "Switch between the Agents and Breakdown tabs (inside a session)"},
			{Key: "/", Description: "Filter by project or session ID (not on Breakdown)"},
			{Key: ".", Description: "Cycle the sort column (agents: tree, Total largest first, Total smallest first; not on Breakdown)"},
			{Key: "↑↓/pgup/pgdn/home/end", Description: "Scroll the Breakdown tab"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Columns",
				Body: "Project: the working directory the session ran in, with your home folded to ~. " +
					"A long path is cut from the left so the project's own name stays visible; a dash means the transcript named none.\n" +
					"Last active: when the session's transcript was last written, in local time.\n" +
					"Session: the start of the session ID. The filter matches the full ID.",
