package agentusageview

import (
	"time"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// runState is what the State column shows for an agent.
type runState int

const (
	stateUnknown runState = iota
	stateRunning
	stateIdle
	stateDone
)

// label returns the text shown in the State column.
func (s runState) label() string {
	switch s {
	case stateRunning:
		return "running"
	case stateIdle:
		return "idle"
	case stateDone:
		return "done"
	default:
		return "unknown"
	}
}

// indicator maps the state onto the activity column's state, so the dot
// repeats what the State column says.
func (s runState) indicator() indicator.State {
	switch s {
	case stateRunning:
		return indicator.Running
	case stateIdle:
		return indicator.Suspended
	case stateDone:
		return indicator.Done
	default:
		return indicator.Unknown
	}
}

// statusClock is what the states are computed against: when the last read
// finished, and whether the session counts as alive (not Settled).
type statusClock struct {
	now   time.Time
	alive bool
}

// quiet reports whether the agent has been silent for strictly more than
// idleAfter. An agent with no timestamp, or one stamped in the future, is
// never quiet.
func (c statusClock) quiet(a agentusage.Agent) bool {
	if a.LastActivity.IsZero() {
		return false
	}
	return c.now.Sub(a.LastActivity) > idleAfter
}

// running is the state of an agent that has not finished: running, or idle
// once it has been silent for long enough.
func (c statusClock) running(a agentusage.Agent) runState {
	if c.quiet(a) {
		return stateIdle
	}
	return stateRunning
}

// subAgentState is the state of one sub-agent. A finished one is done; an
// unfinished one is running or idle whether or not the session is alive; one
// whose meta says nothing is judged the same way while the session is alive,
// and is unknown once it is not.
func (c statusClock) subAgentState(a agentusage.Agent) runState {
	switch {
	case a.State == agentusage.StateFinished:
		return stateDone
	case a.State == agentusage.StateUnfinished || c.alive:
		return c.running(a)
	default:
		return stateUnknown
	}
}

// orchestratorState is the state of the orchestrator, which no file says is
// finished: unknown when the session is not alive, idle only if it has been
// silent for long enough and no sub-agent is running, running otherwise.
func (c statusClock) orchestratorState(a agentusage.Agent, subRunning bool) runState {
	if !c.alive {
		return stateUnknown
	}
	if subRunning {
		return stateRunning
	}
	return c.running(a)
}

// agentStates returns one state per agent, same order. It is pure: the
// clock is a parameter.
func agentStates(agents []agentusage.Agent, c statusClock) []runState {
	out := make([]runState, len(agents))
	subRunning := false
	for i, a := range agents {
		if a.Main {
			continue
		}
		out[i] = c.subAgentState(a)
		subRunning = subRunning || out[i] == stateRunning
	}
	for i, a := range agents {
		if a.Main {
			out[i] = c.orchestratorState(a, subRunning)
		}
	}
	return out
}
package agentusageview

import (
	"fmt"
	"log"
	"math"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/agentusage/pricing"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/datatable"
)

const (
	// minus is the real minus sign (U+2212), never an ASCII hyphen.
	minus = "−"
	// estimateMark prefixes an amount computed from a user-written price table.
	estimateMark = "~"
	// costWidth fits the widest sub-agent cell, "≥ ~$999.99".
	costWidth = 10
	// wholeDollarsFrom is where cents stop being shown.
	wholeDollarsFrom = 999.995
	// maxDollars is the largest amount shown exactly; past it the cell saturates.
	maxDollars = 99999.5
	// saturated is what formatUSD shows past maxDollars: "at least".
	saturated = "$99999+"
)

// formatUSD renders an amount: two decimals up to $999.99, whole dollars from
// $1000, "$99999+" past $99999. A non-zero amount under half a cent is
// "<$0.01", never "$0.00"; a negative one keeps its sign ("−<$0.01"). NaN and
// the infinities are unknown amounts and show a dash. The estimate mark is costCell's, not this function's.
func formatUSD(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return noValue
	}
	if v < 0 {
		return minus + formatUSD(-v)
	}
	switch {
	case v >= maxDollars:
		return saturated
	case v >= wholeDollarsFrom:
		return fmt.Sprintf("$%.0f", math.Floor(v+0.5))
	case v > 0 && v < 0.005:
		return "<$0.01"
	}
	return fmt.Sprintf("$%.2f", v)
}

// costCell is the Est. cost cell: an estimate for the orchestrator, a floor
// (partialMark) for a sub-agent, whose transcript may be incomplete; a dash
// when the cost is unknown. A saturated amount already means "at least", so a
// sub-agent drops the floor mark to stay within costWidth.
func costCell(r agentRow) string {
	if r.cost.Status != pricing.Priced {
		return noValue
	}
	amount := formatUSD(r.cost.USD)
	if r.Main || amount == saturated {
		return estimateMark + amount
	}
	return partialMark + estimateMark + amount
}

// costColumn is the Est. cost column. It has no Less: `.` keeps cycling Total.
func costColumn() datatable.Column[agentRow] {
	return datatable.Column[agentRow]{
		Title: "Est. cost", Sizing: datatable.SizingFixed, MinWidth: costWidth, Optional: true, DropFirst: true, YieldsToContent: true,
		Cell:  costCell,
		Style: func(r agentRow) lipgloss.Style { return dimWhen(r.cost.Status != pricing.Priced) },
	}
}

// pricesFrom builds the price table of a context. The table is read once, when
// the view is built, and a rejected entry is logged once, naming the user's key.
func pricesFrom(cfg *config.Config) pricing.Table {
	if cfg == nil {
		return pricing.Table{}
	}
	table, problems := pricing.FromConfig(cfg.AgentUsage.Prices)
	for _, p := range problems {
		log.Printf("WARN [agentusageview] agent_usage.prices %q: %s", p.Key, p.Reason)
	}
	return table
}

// costShares returns each agent's share of the session's estimated cost, in
// percent, in the order of ests. Agents without a priced estimate get 0 and
// stay out of the denominator. ranked is false when fewer than two agents are
// priced or the priced sum is not a positive number: a share of one is noise.
func costShares(ests []pricing.Estimate) (pct []float64, ranked bool) {
	pct = make([]float64, len(ests))
	var sum float64
	priced := 0
	for _, e := range ests {
		if e.Status == pricing.Priced {
			sum += e.USD
			priced++
		}
	}
	if priced < 2 || math.IsNaN(sum) || math.IsInf(sum, 0) || sum <= 0 {
		return pct, false
	}
	for i, e := range ests {
		if e.Status == pricing.Priced {
			pct[i] = e.USD / sum * 100
		}
	}
	return pct, true
}
package agentusageview

import "github.com/anthnel/devdesk/internal/ui/help"

// GetHelpContent returns the help for `?` (Rule 114).
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title: "Agent usage",
		Description: "The Claude Code sessions found on this machine, newest first. " +
			"Only where and when a session ran is read — nothing a session says.",
		KeyBindings: []help.KeyBinding{
			{Key: "ctrl+r", Description: "Re-read the whole session from the start (at the sessions level: read the sessions again)"},
			{Key: "→/enter", Description: "Open the selected session's agents"},
			{Key: "←/esc", Description: "Back to the sessions"},
			{Key: "tab", Description: "Switch between the Agents and Breakdown tabs (inside a session)"},
			{Key: "/", Description: "Filter by project or session ID (not on Breakdown)"},
			{Key: ".", Description: "Cycle the sort column (agents: tree, Total largest first, Total smallest first; not on Breakdown)"},
			{Key: "↑↓/pgup/pgdn/home/end", Description: "Scroll the Breakdown tab"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Columns",
				Body: "Project: the working directory the session ran in, with your home folded to ~. " +
					"A long path is cut from the left so the project's own name stays visible; a dash means the transcript named none.\n" +
					"Last active: when the session's transcript was last written, in local time.\n" +
					"Session: the start of the session ID. The filter matches the full ID.",
			},
			{
				Title: "Where sessions come from",
				Body: "Claude Code keeps one transcript per session under projects/ in its configuration directory: " +
					"$CLAUDE_CONFIG_DIR when set, otherwise ~/.claude. " +
					"Claude Code deletes old transcripts itself (after 30 days by default), so older sessions disappear from here too.\n" +
					"Sessions that could not be listed (symbolic links, which are refused rather than followed, unreadable directories, " +
					"or sessions beyond the listing cap) are counted as Skipped in the header.",
			},
			{
				Title: "Agents",
				Body: "Opening a session lists its agents: the orchestrator first, then each sub-agent with its type, " +
					"as a tree, with the models used and the tokens in, out, and cached.\n" +
					"The breadcrumb (Sessions › project › session ID) sits on the top border of the frame, not in the footer; " +
					"it is shortened on a narrow terminal and hidden when it no longer fits.\n" +
					"A ≥ before an Out count means a floor: that sub-agent's transcript was still being written, so the real figure is higher.\n" +
					"The orchestrator is the main conversation; its figures are never a floor.\n" +
					"When part of a transcript could not be read, the footer says the totals are approximate.",
			},
			{
				Title: "Agent columns",
				Body: "Agent: the orchestrator, or the sub-agent's type. ID: the start of the sub-agent's ID, long enough to tell two agents of the same type apart; " +
					"the orchestrator shows a dash. The filter matches the full ID.\n" +
					"State: running, idle, done or unknown. A sub-agent that finished is done. " +
					"One still running with no new transcript line for more than 5 min is idle. " +
					"The orchestrator is never done: it is running or idle while updates are live, and unknown once they pause. " +
					"A sub-agent whose state the files do not say is unknown once updates pause.\n" +
					"Tools: distinct tool calls read from the transcript.\n" +
					"Duration: first to last line of the transcript, wall clock, pauses included; a dash when the transcript has no timestamps.\n" +
					"Est. cost: the estimated cost in USD, see Costs. A sub-agent's is a floor (≥ ~) while its transcript may be incomplete; a dash means it cannot be computed.\n" +
					"Breakdown: how the agent's tokens split, in a bar of ten cells. Colors, left to right: Input, Output, Cache write, Cache read. " +
					"A category worth less than half a cell gets no cell of its own. The glyph follows app.gauge_glyph; a dash means no tokens.\n" +
					"Model, In, Out, Cache read, Cache write, Total: models used and token counts. " +
					"On a narrow terminal Cache write goes first, then Est. cost, Cache read, In, Breakdown, Model, State, Duration and Tools. Agent, ID, Out, Total and Share stay. " +
					"Cache write, Est. cost, Cache read, In and Breakdown give way before an agent's type is cut; Model, State, Duration and Tools do not.\n" +
					"Share: the agent's part of the session total, to one decimal, rounded down. " +
					"The orchestrator takes the rounding remainder, so the column adds up to 100%. A dash means the session has no tokens.\n" +
					"Press . to cycle: tree, then Total largest first, then Total smallest first, then the tree again. " +
					"Sorted, the list is flat: the branches go away. The sort stays when you open another session or press ctrl+r.",
			},
			{
				Title: "Breakdown",
				Body: "Press tab inside a session to switch between Agents and Breakdown; esc or ← leaves the session from either tab, and the next session opens on Agents.\n" +
					"The Breakdown tab splits the tokens of the whole session in three blocks, each with a Share and a Tokens column and a Total line: " +
					"by category (Input, Output, Cache write 5 min, Cache write 1 h, Cache read, with a swatch in the color the bar uses), by model, and by agent.\n" +
					"Share is the part of the session's tokens, to one decimal, never of the cost. The rounding remainder goes to the largest line so each block adds up to 100%. " +
					"A session with no tokens shows a dash for every share.\n" +
					"Tokens with no model name in the transcript are counted under unknown. The agent block matches the Share column of the Agents tab.\n" +
					"The panel ignores the filter and the sort: it always covers the whole session, and so do the Agents, Tokens and Est. cost in the header while it is on screen. " +
					"It updates live with the session. A panel taller than the screen scrolls with ↑↓, pgup, pgdn, home and end.",
			},
			{
				Title: "Costs",
				Body: "Est. cost is an estimate, marked ~: tokens times the prices you set, not a bill. DevDesk ships no price. " +
					"An agent whose model has no price shows a dash, never 0, and so does the header total. " +
					"A sub-agent's cost is a floor (≥ ~) because its transcript may be incomplete.\n" +
					"Billed is Claude Code's own total for the session, when it recorded one; a session still running has none. " +
					"Unattributed is Billed minus the estimates: what the estimate does not explain (web search is never priced). " +
					"A negative Unattributed, in orange, means your prices are higher than what was billed. " +
					"When there are no tokens in any agent, Unattributed is Billed (the whole bill). Est. cost follows the filter; Billed and Unattributed do not.\n" +
					"Set agent_usage.prices in the context's config file, in USD per million tokens, all five rates per model:\n" +
					"agent_usage:\n" +
					"  prices:\n" +
					"    claude-example-model:\n" +
					"      input: 3\n" +
					"      output: 15\n" +
					"      cache_write_5m: 3.75\n" +
					"      cache_write_1h: 6\n" +
					"      cache_read: 0.3\n" +
					"Model names match case-insensitively, with or without a trailing -YYYYMMDD date suffix. " +
					"Prices are read again on restart or when you change context; ctrl+r does not re-read them.",
			},
			{
				Title: "Live updates",
				Body: "While a session is open and still active, its figures are refreshed every 2 s and the header shows Updates: live.\n" +
					"Updates pause after 5 min without activity once every agent has finished (a session with an unfinished sub-agent stays live), or when its transcript is deleted: the header shows Updates: paused.\n" +
					"An agent still running with no new transcript line for more than 5 min is shown idle; a long tool call does that too. The header counts the idle agents.\n" +
					"Press ctrl+r to resume. Re-read the whole session from the start with ctrl+r; coming back to the view only reads what changed since the last point read, and goes back to live if the session is being written to.\n" +
					"The list of sessions itself is not live: refresh it with ctrl+r at the sessions level.",
			},
			{
				Title: "Privacy",
				Body: "The sessions list reads the working directory and the file date alone. " +
					"Opening a session also reads its token counts, model names and agent types, and shows only the project's working directory, the date, the session ID, the agent types, the models and the tokens. " +
					"Prompts, replies, tool output and the paths of files a session touched are never displayed and never logged.\n" +
					"Tool calls are counted by their block type alone; their names, inputs and results are never read into DevDesk's data, displayed or logged.",
			},
		},
	}
}
