func TestACleanUsageHasNoStatus(t *testing.T) {
	m := withSessions(t, "/p/a.jsonl")
	m = withAllPriced(t, m)
	m, _ = opened(t, m, "right")
	u := agentusage.Usage{Agents: []agentusage.Agent{
		byModel(agentusage.Agent{Main: true}, mu("model-a", agentusage.Tokens{Output: 320}, 0)),
		byModel(agentusage.Agent{ID: "a01", Type: "coder"}, mu("model-b", agentusage.Tokens{Output: 140}, 0)),
	}}
	m = answer(t, m, u)
	if st := m.status(); st != (sharedcomponents.Status{}) {
		t.Errorf("status = %+v, want none (the empty-table hint is cost_summary_test.go's)", st)
	}
}

func TestStatusPrecedenceAtTheAgentsLevel(t *testing.T) {
	reads := usageMsgs(msgs)
	if len(reads) != 1 {
		t.Fatalf("want one read, got %d", len(reads))
	}
	m, _ = answered(t, m, reads[0])

	if m.agentsLoading || m.agentsErr {
		t.Errorf("agentsLoading=%v agentsErr=%v after a poll, want false, false", m.agentsLoading, m.agentsErr)
	}
	// Not footer(m): at the agents level that includes the tab row.
	if m.footer.IsSet() {
		t.Errorf("a poll must not set a footer message, got %q", m.footer.Text())
	}
	// With every model priced there is no status either: no text, no spinner.
	if st := m.status(); st != (sharedcomponents.Status{}) {
		t.Errorf("status = %+v after a poll, want none (level, spinner and text)", st)
	}
	if got := strings.TrimSpace(ansiRe.ReplaceAllString(m.footer.View(120, m.status()), "")); got != "" {
		t.Errorf("a poll must not write a footer message, got %q", got)
	}
}
